  it("throws NotImplementedError for action_id=is_retainer_checkbox (Wave 8)", async () => {
    const { POST, NotImplementedError } = await import("./route");

    const fx = loadFixture<Record<string, unknown>>("block-actions-checkbox-toggle");
    expect((fx as { actions: { action_id: string }[] }).actions[0].action_id).toBe(
      "is_retainer_checkbox"
    );
    const body = encodePayload(fx);
    const req = makeRequest(body);
    await expect(POST(req as never)).rejects.toBeInstanceOf(NotImplementedError);
