  it("throws NotImplementedError for action_id=task_button_disabled (Wave 8)", async () => {
    const { POST, NotImplementedError } = await import("./route");

    const fx = loadFixture<Record<string, unknown>>("block-actions-button-click");
    const mutated = mutateFixture(fx, {
      actions: [{ ...(fx as { actions: unknown[] }).actions[0] as object, action_id: "task_button_disabled" }],
    } as Partial<Record<string, unknown>>);
    const body = encodePayload(mutated);
    const req = makeRequest(body);
    await expect(POST(req as never)).rejects.toBeInstanceOf(NotImplementedError);
  });

  it("throws NotImplementedError for action_id=target_entity_picker (Wave 8)", async () => {
    const { POST, NotImplementedError } = await import("./route");

    const fx = loadFixture<Record<string, unknown>>("block-actions-button-click");
    const mutated = mutateFixture(fx, {
      actions: [{ ...(fx as { actions: unknown[] }).actions[0] as object, action_id: "target_entity_picker" }],
    } as Partial<Record<string, unknown>>);
    const body = encodePayload(mutated);
    const req = makeRequest(body);
    await expect(POST(req as never)).rejects.toBeInstanceOf(NotImplementedError);
  });

  it("returns 200 for unknown action_id (in-modal interactions handled inline)", async () => {
    const { POST } = await import("./route");

    const fx = loadFixture<Record<string, unknown>>("block-actions-button-click");
    const mutated = mutateFixture(fx, {
      actions: [{ ...(fx as { actions: unknown[] }).actions[0] as object, action_id: "some_inline_action" }],
    } as Partial<Record<string, unknown>>);
    const body = encodePayload(mutated);
    const req = makeRequest(body);
    const res = await POST(req as never);
    expect(res.status).toBe(200);
  });

  it("returns 200 when block_actions payload has no actions array", async () => {
    const { POST } = await import("./route");

    const body = encodePayload({ type: "block_actions" });
    const req = makeRequest(body);
    const res = await POST(req as never);
    expect(res.status).toBe(200);
  });
});

