  });

  it.each([
    "runway_new_task",
    "runway_new_project",
    "runway_new_team_member",
    "runway_edit_task",
    "runway_edit_project",
    "runway_edit_team_member",
  ])("throws NotImplementedError for callback_id=%s (Wave 10)", async (callbackId) => {
    const { POST, NotImplementedError } = await import("./route");

    const fx = loadFixture<Record<string, unknown>>("view-submission-task");
    const mutated = mutateFixture(fx, {
