/**
 * Slack interactivity webhook handler (Phase 1 scaffold).
 *
 * POST /api/slack/interactivity
 *
 * Accepts every Slack interactive payload type:
 *   - block_actions      (button clicks, checkbox toggles, picker changes)
 *   - view_submission    (modal "Save" submit)
 *   - view_closed        (modal cancel / dismiss with notify_on_close=true)
 *   - shortcut           (global / message shortcuts — currently unused)
 *
 * Security mirrors `/api/slack/events`:
 *   - HMAC-SHA256 signature verification on every request via
 *     `verifySlackSignature` (5-minute replay window enforced inside).
 *   - Tampered or stale requests → 401.
 *   - Misconfigured server (no `SLACK_SIGNING_SECRET`) → 400 per pre-plan v7.
 *
 * Body shape: Slack sends interactive payloads as
 * `application/x-www-form-urlencoded` with a single `payload=<json>` field —
 * NOT plain JSON like the Events API. We parse the URLSearchParams and
 * `JSON.parse` the `payload` value before routing.
 *
 * Routing strategy: dispatch on `payload.type`, then drill in by
 * `actions[0].action_id` (block_actions) or `view.callback_id`
 * (view_submission/view_closed). Slots that Phase 2/3 wires throw
 * `NotImplementedError` so Builder 7/8/10/11 can grep for the marker and
 * replace each branch surgically without inventing routing.
 *
 * Phase 1 scope is *only* the dispatch shape + HMAC posture. No DB writes,
 * no Slack API calls, no Inngest dispatch.
 */

import { verifySlackSignature } from "@/lib/slack/verify";

// -----------------------------------------------------------------------------
// Payload types — discriminated union, just enough for type-safe dispatch.
// Phase 2/3 builders extend these in-place as concrete fields are needed.
// -----------------------------------------------------------------------------

/** Single action element inside a block_actions payload's `actions` array. */
interface SlackAction {
  action_id?: string;
  block_id?: string;
  type?: string;
  value?: string;
  // Slack adds many other fields per action type; carry them through opaquely.
  [key: string]: unknown;
}

interface SlackBlockActionsPayload {
  type: "block_actions";
  user?: { id?: string; team_id?: string };
  team?: { id?: string };
  trigger_id?: string;
  response_url?: string | null;
  view?: SlackView;
  actions?: SlackAction[];
  [key: string]: unknown;
}

/** A Slack modal view as it appears inside view_submission/view_closed. */
interface SlackView {
  id?: string;
  callback_id?: string;
  private_metadata?: string;
  state?: { values?: Record<string, unknown> };
  [key: string]: unknown;
}

interface SlackViewSubmissionPayload {
  type: "view_submission";
  user?: { id?: string };
  team?: { id?: string };
  view?: SlackView;
  [key: string]: unknown;
}

interface SlackViewClosedPayload {
  type: "view_closed";
  user?: { id?: string };
  team?: { id?: string };
  view?: SlackView;
  is_cleared?: boolean;
  [key: string]: unknown;
}

interface SlackShortcutPayload {
  type: "shortcut";
  callback_id?: string;
  user?: { id?: string };
  team?: { id?: string };
  trigger_id?: string;
  [key: string]: unknown;
}

export type SlackInteractionPayload =
  | SlackBlockActionsPayload
  | SlackViewSubmissionPayload
  | SlackViewClosedPayload
  | SlackShortcutPayload;

// -----------------------------------------------------------------------------
// Sentinel error — Wave 8/10/11 builders replace each `throw new
// NotImplementedError(...)` with the real handler. Tests assert on the class
// (not the string) so subsequent edits don't break the dispatch contract.
// -----------------------------------------------------------------------------

export class NotImplementedError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "NotImplementedError";
  }
}

// -----------------------------------------------------------------------------
// Route handler
// -----------------------------------------------------------------------------

export async function POST(request: Request): Promise<Response> {
  // Read the raw body BEFORE any parsing — HMAC is computed over the exact
  // bytes Slack sent, including URL-encoding.
  const rawBody = await request.text();

  const signingSecret = process.env.SLACK_SIGNING_SECRET;
  const signature = request.headers.get("x-slack-signature");
  const timestamp = request.headers.get("x-slack-request-timestamp");

  if (!signingSecret || !signature || !timestamp) {
    return new Response("Bad Request", { status: 400 });
  }

  if (!verifySlackSignature(signingSecret, signature, timestamp, rawBody)) {
    return new Response("Unauthorized", { status: 401 });
  }

  // URL-decode the form body and pull the single `payload` field.
  const params = new URLSearchParams(rawBody);
  const payloadStr = params.get("payload");
  if (!payloadStr) {
    return new Response("Bad Request", { status: 400 });
  }

  let payload: SlackInteractionPayload;
  try {
    payload = JSON.parse(payloadStr) as SlackInteractionPayload;
  } catch {
    return new Response("Bad Request", { status: 400 });
  }

  switch (payload.type) {
    case "block_actions":
      return await handleBlockActions(payload);
    case "view_submission":
      return await handleViewSubmission(payload);
    case "view_closed":
      return await handleViewClosed(payload);
    case "shortcut":
      return await handleShortcut(payload);
    default:
      return new Response("Bad Request", { status: 400 });
  }
}

// -----------------------------------------------------------------------------
// block_actions dispatch
// -----------------------------------------------------------------------------

async function handleBlockActions(
  payload: SlackBlockActionsPayload
): Promise<Response> {
  const actionId = payload.actions?.[0]?.action_id;

  switch (actionId) {
    case "open_create_modal":
      // Wave 8 — opens a modal via `views.open`.
      throw new NotImplementedError(
        "block_actions/open_create_modal — Wave 8 wires this"
      );
    case "is_retainer_checkbox":
      // Wave 8 — toggles retainer-only fields via `views.update`.
      throw new NotImplementedError(
        "block_actions/is_retainer_checkbox — Wave 8 wires this"
      );
    case "task_button_disabled":
      // Wave 8 — disambiguation flow when create-task path needs a parent.
      throw new NotImplementedError(
        "block_actions/task_button_disabled — Wave 8 wires this"
      );
    case "target_entity_picker":
      // Wave 8 — switches modal contents based on selected target entity.
      throw new NotImplementedError(
        "block_actions/target_entity_picker — Wave 8 wires this"
      );
    default:
      // Repeater rows, in-modal pickers without `dispatch_action`, and any
      // action_id we don't explicitly handle on the server are no-ops here:
      // Slack handles the visual state client-side, and we ack with 200 so
      // Slack doesn't show the "didn't work" warning to the user.
      return new Response("OK", { status: 200 });
  }
}

// -----------------------------------------------------------------------------
// view_submission dispatch
// -----------------------------------------------------------------------------

async function handleViewSubmission(
  payload: SlackViewSubmissionPayload
): Promise<Response> {
  const callbackId = payload.view?.callback_id;
  if (!callbackId) {
    return new Response("Bad Request", { status: 400 });
  }

  switch (callbackId) {
    case "runway_new_task":
    case "runway_new_project":
    case "runway_new_team_member":
    case "runway_edit_task":
    case "runway_edit_project":
    case "runway_edit_team_member":
      // Wave 10 — server-side validation + Inngest dispatch for the write.
      throw new NotImplementedError(
        `view_submission/${callbackId} — Wave 10 wires this`
      );
    default:
      return new Response("Bad Request", { status: 400 });
  }
}

// -----------------------------------------------------------------------------
// view_closed dispatch
// -----------------------------------------------------------------------------

async function handleViewClosed(
  _payload: SlackViewClosedPayload
): Promise<Response> {
  // Wave 11 — telemetry + draft cleanup when a user dismisses the modal.
  throw new NotImplementedError("view_closed — Wave 11 wires this");
}

// -----------------------------------------------------------------------------
// shortcut dispatch
// -----------------------------------------------------------------------------

async function handleShortcut(
  _payload: SlackShortcutPayload
): Promise<Response> {
  // No global or message shortcuts wired yet. Ack so Slack doesn't retry.
  return new Response("OK", { status: 200 });
}

